    public function label($consignment, $labelType = 'pdf', $size = '') {

        $output = array();
        $this->user = SessionManager::getUser();
        $this->userAccount = new CustomerAccount($this->user->getUserAccountId());
        $this->serviceValues = new Services($consignment->getServiceId());
        $this->country = new Country($consignment->getCountryId());

        /*
         *  Get Service  constants 
         */

        $serviceAgentConstantFilter = new ServiceConstantValueFilter();
        $serviceAgentConstantFilter->addFilter("service_id = '" . $consignment->getServiceId() . "' AND agent_id = '" . $consignment->getAgentId() . "' ");
        $serviceAgentConstant = $serviceAgentConstantFilter->getConstantList("c.constant 'constant_name', scv.constant_value 'constant_value'");

        if (count($serviceAgentConstant) > 0) {
            foreach ($serviceAgentConstant as $serviceAgentConstantData) {
                $this->constants[$serviceAgentConstantData->getConstantName()] = $serviceAgentConstantData->getConstantValue();
            }
        }
        
        

        if (trim(@$this->constants['DAI_POST_LABEL_URL']) == '' && trim(@$this->constants['DAI_POST_ACCOUNT']) == '') {
            $output['STATUS'] = 'ERROR';
            $output['MESSAGE'] = "Please check service constants. Please contact to itsupport@oneworldexpress.com";
            return $output;
        }
        
        if (trim(@$this->constants['DAI_POST_SHIPPER_COUNTRY']) == '' || $this->constants['DAI_POST_SHIPPER_COUNTRY'] <= 0) {
            $output['STATUS'] = 'ERROR';
            $output['MESSAGE'] = "Please check service constants. Please contact to itsupport@oneworldexpress.com";
            return $output;
        }
        
        $senderCountry = new Country($this->constants['DAI_POST_SHIPPER_COUNTRY']);

        /*
         *  Get Tracking Number ranges
         */
        $parcel_list = $consignment->getParcels();
        $parcel_count = sizeof($parcel_list);
        $parcel_idx = 0;

        $licence_plate = "";
        $requestXml = "";

        $date = gmdate('Y-m-d\TH:i:s\Z');

        $consigneeName = '';
        if ($consignment->getContact() == '')
            $consigneeName = $consignment->getCompany();
        else
            $consigneeName = $consignment->getContact();
        $this->constants['DAI_POST_ACCOUNT'] = "ONW";

        $state = "";
        if($this->country->getIso() == 'AU'){
            //if(trim($consignment->getState()) == '')
                $state = $this->getAuStates($consignment->getCity());
        } else {
            $state = $consignment->getState();
        }
        
        $request_xml = '<xml>
                                <shipment service="' . $this->constants['DAI_POST_LABEL_SERVICE'] . '" labelformat = "' . strtoupper($labelType) . '" account="' . $this->constants['DAI_POST_ACCOUNT'] . '" datetime="' . $date . '" reference="' . $consignment->getHawb() . '" value="' . $consignment->getValue() . '" currency="' . $consignment->getCurrency() . '" uom="kg" weight="' . $consignment->getWeight() . '" returntoshipper="1" originterminal="' . $this->constants['DAI_POST_ORIGINAL_TERMINAL'] . '">
                                <shipper name="' . $this->constants['DAI_POST_SHIPPER_NAME'] . '" attention="' . $this->constants['DAI_POST_SHIPPER_COMPANY'] . '" addr1="' . $this->constants['DAI_POST_SHIPPER_ADDRESS_LINE_1'] . '" addr2="" city="' . trim($this->constants['DAI_POST_SHIPPER_CITY']) . '" state="' . $this->constants['DAI_POST_SHIPPER_STATE'] . '" country="' . $senderCountry->getIso() . '" postal="' . $this->constants['DAI_POST_SHIPPER_POST_CODE'] . '" phone="' . $this->constants['DAI_POST_SHIPPER_TELEPHONE'] . '" email="' . $this->constants['DAI_POST_SHIPPER_EMAIL_ADDRESS'] . '" />
                                <consignee name="' . utf8_encode($consigneeName) . '" attention="' . utf8_encode($consignment->getCompany()) . '" addr1="' . utf8_encode($consignment->getAddressLine1()) . '"  addr2="' . utf8_encode($consignment->getAddressLine2()) . '" city="' . utf8_encode($consignment->getCity()) . '" state="' . utf8_encode($state) . '" country="' . $this->country->getIso() . '" postal="' . $consignment->getPostCode() . '" phone="' . $consignment->getTelephone() . '"  email="' . $consignment->getEmail() . '" />
                                <item description="' . utf8_encode(str_replace("&"," - ",$consignment->getDescription())) . '" qty="' . $consignment->getNumberPieces() . '" unit="pc" value="' . $consignment->getValue() . '" origin="GB" /></shipment></xml>';

        $ch = curl_init();

        curl_setopt($ch, CURLOPT_URL, $this->constants['DAI_POST_LABEL_URL']);

        $headers = array(
            'Content-Type:application/json',
            'Authorization: Basic ' . base64_encode($this->constants['DAI_POST_LABEL_USERNAME'] . ":" . $this->constants['DAI_POST_LABEL_PASSWORD']) // <---
        );
        curl_setopt($ch, CURLOPT_TIMEOUT, 30); //timeout after 30 seconds
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
        curl_setopt($ch, CURLOPT_HTTPAUTH, CURLAUTH_ANY);

        curl_setopt($ch, CURLOPT_POSTFIELDS, $request_xml);
        curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
        $result = curl_exec($ch);

        $consignment->setApiData(print_r($request_xml, true), print_r($result, true), 'Dia_post');

        $status_code = curl_getinfo($ch, CURLINFO_HTTP_CODE);   //get status code

        curl_close($ch);

        $xml = simplexml_load_string($result);

        if (isset($xml->error)) {
            foreach ($xml->error[0]->attributes() as $a => $b) {
                if ($a == 'description')
                    $output["STATUS"] = "ERROR";
                $output["MESSAGE"] = $b;
                return $output;
            }
        }

        if (isset($xml->shipmentresponse)) {
            $licence_plate_array = array();
            foreach ($xml->shipmentresponse[0]->attributes() as $a => $b) {

                if ($a == 'context') {
                    $output["STATUS"] = "ERROR";
                    $output["MESSAGE"] = $b;
                    return $output;
                }
                if ($a == 'tracknbr') {

                   
                    $licence_plate = (string)$b;
                    $licence_plate_array[] = $licence_plate;
                    if (count($parcel_list) > 0) {
                        //   $parcel_count = sizeof($parcel_list);
                        foreach ($parcel_list as $parcel) {
                            $parcel->setTrackingNumber($licence_plate);
                            $parcel->setParcelLabel(date('Y_m_d') . '/' . $licence_plate. ".pdf");
                            $parcel->save();
                        }
                    }
                }

                if ($a == 'label') {
                    $mergeFileName = SETTING_DIR_REMOTE . '_assets/pdf/' . date('Y_m_d') . '/' . $consignment->getId() . ".pdf";

                    $pdf = fopen($mergeFileName, 'w');
                    fwrite($pdf, base64_decode($b));
                    fclose($pdf);
                    
                    $pieceFileName = SETTING_DIR_REMOTE . '_assets/pdf/' . date('Y_m_d') . '/' . $licence_plate . ".pdf";

                    $pdf = fopen($pieceFileName, 'w');
                    fwrite($pdf, base64_decode($b));
                    fclose($pdf);
                    
                }
            }
            $output['STATUS'] = 'SUCCESS';
            $output['LABEL'] = date('Y_m_d') . '/' . $consignment->getId() . ".pdf";
            $output['TRACKING_NUMBER'] = $licence_plate_array;
            //       return "SUCCESS||".SETTING_MAIN_URL."_assets/pdf/".date('Y_m_d').'/'.$consignment->getId().".pdf||".$licence_plate;
        }

        return $output;
    }

    public function tracking($trackingNo, $trackBy = 'shipment', $EDI = false) {
        require_once(BASE_PATH . "includes/labels/daiposttrackingstatus.class.php");
        
        $tracking = new Tracking();
        $consignmentFilter = new ConsignmentFilter();
        $consignmentFilter->addAwbAndHawbOrFilter($trackingNo);
        $consignment = $consignmentFilter->getColumnList('*');

        $serviceAgentConstantFilter = new ServiceConstantValueFilter();
        $serviceAgentConstantFilter->addFilter("service_id = '" . $consignment[0]->getServiceId() . "' AND agent_id = '" . $consignment[0]->getAgentId() . "' ");
        $serviceAgentConstant = $serviceAgentConstantFilter->getConstantList("c.constant 'constant_name', scv.constant_value 'constant_value'");

        if (count($serviceAgentConstant) > 0) {
            foreach ($serviceAgentConstant as $serviceAgentConstantData) {
                $this->constants[$serviceAgentConstantData->getConstantName()] = $serviceAgentConstantData->getConstantValue();
            }
        }

        $jsonArray = array();
        $username = $this->constants['DAI_POST_LABEL_USERNAME'];
        $password = $this->constants['DAI_POST_LABEL_PASSWORD'];
        $url = $this->constants['DAI_POST_LABEL_URL'];

        $request_xml = '<xml><tracking tracknbr="' . $trackingNo . '" /></xml>';

        $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, $url);
        $headers = array(
            'Content-Type:application/json',
            'Authorization: Basic ' . base64_encode($username . ":" . $password)
        );

        curl_setopt($ch, CURLOPT_TIMEOUT, 30); //timeout after 30 seconds
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
        curl_setopt($ch, CURLOPT_HTTPAUTH, CURLAUTH_ANY);
        curl_setopt($ch, CURLOPT_POSTFIELDS, $request_xml);
        curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
        $result = curl_exec($ch);

        $xml = new SimpleXMLElement($result);

        $json = json_encode($xml);
        //$jsonArray = json_decode($json, true)['trackingresponse']['trackingevent'];
        //$jsonArray = array_reverse($jsonArray);
        
        $parcelStatusTmp = [];
        $parcelStatusTmp = json_decode($json, true)['trackingresponse']['trackingevent'];
        if (isset($parcelStatusTmp[0]))
            $parcelStatus = $parcelStatusTmp;
        else
            $parcelStatus[] = $parcelStatusTmp;
                        
        $jsonArray = array_reverse($parcelStatus);   
        //print_r($jsonArray); die;
        
        $entityId = 0;
        if ($trackBy == 'shipment') {
            $shipmenObj = new ConsignmentFilter();
            $shipmenObj->addawbFilter($trackingNo);
            $shipmentDataArray = $shipmenObj->getColumnList('c.awb');
            if (count($shipmentDataArray) > 0) {
                $shipmentData = $shipmentDataArray[0];
                $entityId = $shipmentData->getId();
            }
        } else if ($trackBy == 'parcel') {
            $parcelObj = new ParcelFilter();
            $parcelObj->addTrackingNumberFilter($trackingNo);
            $parcelDataArray = $parcelObj->getColumnList('p.id, p.tracking_number, p.consignment_id');
            if (count($parcelDataArray) > 0) {
                $parcelData = $parcelDataArray[0];
                $entityId = $parcelData->getId();
            }
        }
        
        ////////////////////// Carrier Received ////////////////////////////////
            
        $trackingDataFilterObj = new TrackingDataFilter();
        $trackingDataFilterObj->addFieldFilter('    tracking_number', $trackingNo);        
        $trackingDataFilterObj->addFilter("carrier_code not in ('','FI01')");
        $trackingEvents = $trackingDataFilterObj->getList();

        if(count($trackingEvents) > 0)
        {
            $carrierReceivedCheck = 0;   // there is already carrier received event                
            $trackingDataFilterObj = new TrackingDataFilter();
            $trackingDataFilterObj->addFieldFilter('    tracking_number', $trackingNo);        
            $trackingDataFilterObj->addFilter("status_code_id = '148'");
            $CarrierReceivedObj = $trackingDataFilterObj->getList();   
            if(count($CarrierReceivedObj) >0 )
            {
                $carrierCodeCarrierReceived = $CarrierReceivedObj[0]->getCarrierCode();
                $carrierReceivedStatusCode = $CarrierReceivedObj[0]->getStatusCodeId();   
            }
        }
        else
        {
            $carrierReceivedCheck = 1; // No carrier received Event
        } 
        ////////////////////// Carrier Received ////////////////////////////////
                    
        if (count($jsonArray) > 0) 
        {
            $parcelEntity = new Parcel($entityId);
            $finalStatusCode = $parcelEntity->getParcelStatusCode();
            $deliveredArray = array('FD01','FD02','FD03','FD31');  
                      
            foreach ($jsonArray as $data) 
            {
                foreach ($data as $event) 
                {
                    $EventCode = $event['code'];
                    $Signatory = '';
                    $daiPostTrackingStatus = DaiPostTrackingStatus::getOweStatusCode($EventCode);
                    $dateTime = date("Y-m-d H:i", strtotime($event['eventdate']));
                    $ServiceAreaDescription = $event['country'];
                    $EventDescription = $event['description'];
                    // Dont enter any other event code if it is against 148 Event Code
                    if($carrierCodeCarrierReceived == $EventCode)
                    {
                        continue;
                    }
                    ////////////////////// Carrier Received ////////////////////////////////
                    if($carrierReceivedCheck == 1 && $EventCode != 'FI01' )
                    {
                        $spTrackingStatus = '148';
                        $carrierReceivedCheck = 0 ;                        
                    }
                    else
                    {
                        $spTrackingStatus = DaiPostTrackingStatus::getOweStatusCode($EventCode);
                    }            
                    ////////////////////// Carrier Received ////////////////////////////////
                    
                    $result = $tracking->saveTrackPoint($entityId, $trackBy, $dateTime, $trackingNo, $spTrackingStatus, $ServiceAreaDescription, $EventCode, $EventDescription, $deliveredArray, $finalStatusCode);                                        
                    if($result == true)
                    {
                        break;
                    }
                }// internal foreach               
            }  // end foreach 

            $tracking->saveConsignmentTrackingStatus($trackingNumber, 'DaiPostTrackingStatus');      
        }
    }

    public function sendData($tracking_numbers = array()) {
        $output = [];
        $agentServiceArray = [];
        $consignmentData = new ConsignmentFilter();
        $consignmentData->addFilter("     s.carrier_id= '159'", "servicefilter");
        $consignmentData->addFilter("     c.send_courier_data= '0'", "consignmentfilter");
        if (!empty($tracking_numbers)) {
            $consignmentData->addFilter("AND pc.tracking_number in ('" . implode("','", $tracking_numbers) . "') and pc.tracking_number <> ''", "parcelJoinFilter");
        }
        $consignmentData->addGroupBy(" c.service_id, c.agent_id ");

        $consignmentServiceAgent = $consignmentData->getColumnList("c.service_id, c.agent_id");
        if (count($consignmentServiceAgent) > 0) {
            foreach ($consignmentServiceAgent as $agentData) {
                $agentServiceArray['services'][] = $agentData->getServiceId();
                $agentServiceArray['agent'][] = $agentData->getAgentId();
            }
        } else {
            $output["STATUS"] = "ERROR";
            $output["MESSAGE"] = "Please check we did not find any agent and services for data to send.";
        }

        if (!empty($agentServiceArray['services'])) {

            foreach ($agentServiceArray['services'] as $key => $serviceid) {

                $serviceid = trim($serviceid);
                $agentid = trim($agentServiceArray['agent'][$key]);

                $this->serviceValues = new Services($serviceid);

                // GET CONSTANTS AS PER SERVICE AND AGENT
                $serviceAgentConstantFilter = new ServiceConstantValueFilter();
                $serviceAgentConstantFilter->addFilter("service_id = '" . $serviceid . "' AND agent_id = '" . $agentid . "' ");
                $serviceAgentConstant = $serviceAgentConstantFilter->getConstantList("c.constant 'constant_name', scv.constant_value 'constant_value'");
                if (count($serviceAgentConstant) > 0) {
                    foreach ($serviceAgentConstant as $serviceAgentConstantData) {
                        $this->constants[$serviceid][$serviceAgentConstantData->getConstantName()] = $serviceAgentConstantData->getConstantValue();
                    }
                }
                if (!empty($this->constants[$serviceid])) {
                    // GET ALL THE CONSIGNMENT WITH THE PARCEL FOR PREPARE  FILE
                    $consignmentShipmentDataFilter = new ConsignmentFilter();
                    $consignmentShipmentDataFilter->addFilter("     c.service_id = '" . $serviceid . "' AND c.agent_id = '" . $agentid . "' ", "consignmentfilter");
                    $consignmentShipmentDataFilter->addFilter("     c.send_courier_data= '0'", "consignmentfilter");
                    if (!empty($tracking_numbers))
                        $consignmentShipmentDataFilter->addFilter("     AND pc.tracking_number in ('" . implode("','", $tracking_numbers) . "') and pc.tracking_number <> ''", "parcelJoinFilter");
                    $consignmentShipmentData = $consignmentShipmentDataFilter->getColumnList(" c.id 'consignment_id', s.carrier_id ,s.code 'service_code',
                     con.region 'country_region', c.service_id, c.weight, c.hawb, c.description, c.company, c.country_id,c.awb,c.date_created,c.value,
                      c.contact, c.address_line_1, c.address_line_2, c.city, c.postcode, c.telephone, c.other_routing_code, routing_code_eur ");

                    if (count($consignmentShipmentData) > 0) {
                        $consignmentIdArray = [];
                        foreach ($consignmentShipmentData as $consignmentItemData) {

                            $consignmentId = $consignmentItemData->getConsignmentId();
                            $consignmentIdArray[] = $consignmentId;
                            $carrierId = $consignmentItemData->getCarrierId();
                            $this->record_array[] = $this->getShipmentRecord($consignmentItemData);
                        }
                        $carrierId = $this->serviceValues->getCarrierId();
                        $agentid = trim($agentServiceArray['agent'][$key]);
                        $run_number = CarrierDataFileLog::generateRunNumber($carrierId, $agentid);
                        $fastway_file = "OneWorld-manifest-" . $run_number;

                        $carrierDataFileLog = new CarrierDataFileLog();
                        $carrierDataFileLog->setCarrierId($carrierId);
                        $carrierDataFileLog->setAgentId($agentid);
                        $carrierDataFileLog->setFileName($fastway_file);
                        $carrierDataFileLog->setRunNumber($run_number);
                        $carrierDataFileLog->save();

                        if ($this->sendBookings($this->constants[$serviceid])) {
                            if (!empty($consignmentIdArray)) {

                                $sql = "UPDATE consignment SET booked_file_id = '" . $fastway_file . "' 
                                        WHERE id IN (" . implode("','", $consignmentIdArray) . ")  AND id <> '0' 
                                        AND  shipment_status not in ('" . Consignment::STATUS_RECYCLED . "','" . Consignment::STATUS_READY_TO_PRINT . "','" . Consignment::STATUS_INVALID . "')";
                                DbAccess3::runQuery($sql);
                                $output["STATUS"] = "SUCCESS";
                                $output["MESSAGE"] = "System has successfully send data.";
                            } else {
                                $output["STATUS"] = "ERROR";
                                $output["MESSAGE"] = "No consignment found to send data to carrier.";
                            }
                        } else {
                            $output["STATUS"] = "ERROR";
                            $output["MESSAGE"] = "Please check constants, System not able to find FTP details to send data to fastway. Please fix it ASAP";
                        }
                    } else {
                        
                    }
                }
            }
        }
    }

