    public function manifest($consignmentObj) {
        $manifestId = '';
        // $trackingNumber = $consignmentObj[0]->getAwb();
        $serviceAgentConstantFilter = new ServiceConstantValueFilter();
        $serviceAgentConstantFilter->addFilter("service_id = '" . $consignmentObj[0]->getServiceId() . "' AND agent_id = '" . $consignmentObj[0]->getAgentId() . "' ");
        $serviceAgentConstant = $serviceAgentConstantFilter->getConstantList("c.constant 'constant_name', scv.constant_value 'constant_value'");

        if (count($serviceAgentConstant) > 0) {
            foreach ($serviceAgentConstant as $serviceAgentConstantData) {
                $this->constants[$serviceAgentConstantData->getConstantName()] = $serviceAgentConstantData->getConstantValue();
            }
        }

        if ($manifestId > 0 && count($conList) > 0) {
            $request_xml = '<xml><manifest jobnumber="' . $manifestId . '" datetime="' . date("Y-m-d") . "T" . date("H:i:s") . "Z" . '">';

            foreach ($consignmentObj as $con) {
                $request_xml .= '<shipment tracknbr="' . $con->getAwb() . '" />';
            }

            $request_xml .= '</manifest></xml>';

            $ch = curl_init();


            curl_setopt($ch, CURLOPT_URL, $this->constants['DAI_POST_LABEL_URL']);
            $headers = array(
                'Content-Type:application/json',
                'Authorization: Basic ' . base64_encode($this->constants['DAI_POST_LABEL_USERNAME'] . ":" . $this->constants['DAI_POST_LABEL_PASSWORD']) // <---
            );
            curl_setopt($ch, CURLOPT_TIMEOUT, 30); //timeout after 30 seconds
            curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
            curl_setopt($ch, CURLOPT_HTTPAUTH, CURLAUTH_ANY);
            curl_setopt($ch, CURLOPT_POSTFIELDS, $request_xml);
            curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);

            $result = curl_exec($ch);

            //mail("kazim@oneworldexpress.com", "DAI POST", $request_xml . " " . $result);

            $xml = simplexml_load_string($result);
            $json = json_encode($xml);
            $array = json_decode($json, TRUE);

            $manifestArray = $array['manifestresponse'];


            foreach ($manifestArray as $item) {
                if ($item['manifestpdf'] != '') {
                    //$item['manifestpdf'];
                    $pdf_decoded = base64_decode($item['manifestpdf']);
                    $path = "../_assets/daipost/" . date("Y_m_d") . "/";
                    if (!file_exists($path))
                        @mkdir($path, 0777);
                    $mergeFileName = $path . '' . $manifestId . " " . date('YmdHis') . ".pdf";
                    $pdf = fopen($mergeFileName, 'w');
                    fwrite($pdf, $pdf_decoded);
                    fclose($pdf);

                    $manifest = new manifest($manifestId);
                    $manifest->setpdfFile($mergeFileName);
                    $manifest->save();
                }
            }
        }
    }

